import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function designed to exhibit specific ELA features.

    The function combines a skewed quadratic component, a linear term with interactions,
    and a radially symmetric term.

    f(x) = (sum(x^2))^0.5 + 0.3 * skewed_quadratic(x) + 0.1 * linear_interactions(x)

    where:

    skewed_quadratic(x) = sum((x + 2)^2)
    linear_interactions(x) = sum(x_i * x_j for all i < j)
    """

    def skewed_quadratic(x):
      return np.sum((x + 2)**2)

    def linear_interactions(x):
      interactions = 0
      for i in range(len(x)):
        for j in range(i + 1, len(x)):
          interactions += x[i] * x[j]
      return interactions

    return np.sqrt(np.sum(x**2)) + 0.3 * skewed_quadratic(x) + 0.1 * linear_interactions(x)
